<script lang="ts">import {enhance} from '$app/forms';import type {PageData,ActionData} from './$types';import Icon from '$lib/components/Icon.svelte';export let data:PageData;export let form:ActionData;</script>
<svelte:head><title>Trabalhos — FRAME</title></svelte:head><div class="admin-heading"><div><h1>Trabalhos</h1><p>Organize os trabalhos que mostram o seu olhar.</p></div><a class="btn small accent" href="/admin/trabalhos/novo"><Icon name="plus" size={16}/> Novo trabalho</a></div>{#if form?.error}<div class="alert" role="alert">{form.error}</div>{:else if form?.success}<div class="alert success" role="status">{form.success}</div>{/if}<section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Projeto</th><th>Categoria</th><th>Estado</th><th>Ordem</th><th>Ações</th></tr></thead><tbody>{#each data.projects as project}<tr><td><a class="table-project" href={`/admin/trabalhos/${project.id}`}><img src={project.coverUrl||'/demo/ritmo.webp'} alt=""/><div><b>{project.title}</b><span>/{project.slug}</span></div></a></td><td data-label="Categoria">{data.categories.find(c=>c.id===project.categoryId)?.name||'Sem categoria'}</td><td data-label="Estado"><span class="status-tag" class:published={project.status==='published'}>{project.status==='published'?'Publicado':'Rascunho'}</span></td><td data-label="Ordem"><div class="row-actions"><span>{project.sortOrder}</span><form method="POST" action="?/move" use:enhance><input type="hidden" name="id" value={project.id}/><button name="direction" value="-1" aria-label={`Mover ${project.title} para antes`}>↑</button><button name="direction" value="1" aria-label={`Mover ${project.title} para depois`}>↓</button></form></div></td><td data-label="Ações"><div class="row-actions"><a class="text-link" style="font-size:11px" href={`/admin/trabalhos/${project.id}`}>Editar</a><form method="POST" action="?/status" use:enhance><input type="hidden" name="id" value={project.id}/><button>{project.status==='draft'?'Publicar':'Despublicar'}</button></form><form method="POST" action="?/delete" onsubmit={event=>{if(!confirm(`Excluir o trabalho “${project.title}”? Esta ação não remove a imagem da biblioteca.`))event.preventDefault();}}><input type="hidden" name="id" value={project.id}/><button>Excluir</button></form></div></td></tr>{:else}<tr><td colspan="5" class="admin-empty">Nenhum trabalho ainda.<br/><a href="/admin/trabalhos/novo" class="text-link">Criar o primeiro trabalho</a></td></tr>{/each}</tbody></table></div></section><p class="fineprint">A ordem menor aparece primeiro. Rascunhos ficam privados até você publicar.</p>
